def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find recurring separator lines: these contain the dominant grid
    # background, while the open rectangles contain a different fill color.
    colors = {}
    for row in grid:
        for v in row:
            colors[v] = colors.get(v, 0) + 1
    bg = max(colors, key=colors.get)

    def line_score(i, horizontal):
        line = grid[i] if horizontal else [grid[r][i] for r in range(h)]
        return line.count(bg) / len(line)

    def separators(horizontal):
        n = h if horizontal else w
        scores = [line_score(i, horizontal) for i in range(n)]
        candidates = [i for i, s in enumerate(scores) if s > 0.65]
        if len(candidates) < 2:
            return []
        gaps = [b-a for a, b in zip(candidates, candidates[1:])]
        step = max(set(gaps), key=gaps.count)
        return [i for i in candidates
                if (i-candidates[0]) % step == 0]

    rs, cs = separators(True), separators(False)
    if len(rs) < 2 or len(cs) < 2:
        return grid

    nr, nc = len(rs)-1, len(cs)-1
    out = []
    for y in range(nr):
        row = []
        for x in range(nc):
            # Default to the dominant color inside the cell.
            vals = [grid[r][c]
                    for r in range(rs[y]+1, rs[y+1])
                    for c in range(cs[x]+1, cs[x+1])]
            if vals:
                counts = {}
                for v in vals:
                    counts[v] = counts.get(v, 0) + 1
                cell = max(counts, key=counts.get)
            else:
                cell = bg
            row.append(cell)
        out.append(row)

    # Marker colors are placed on separator intersections. A crossing
    # belongs to the cell immediately down and right of it.
    for y, r in enumerate(rs[:-1]):
        for x, c in enumerate(cs[:-1]):
            v = grid[r][c]
            if v != bg:
                out[y][x] = v
    return out
