def transform(grid):
    h, w = len(grid), len(grid[0])

    # The 8-filled blocks are the cells; lines of 5 form their boundaries.
    # The colored boundary intersections encode the compact output.
    rs = [r for r in range(h) if all(v == 5 for v in grid[r])]
    cs = [c for c in range(w) if all(grid[r][c] == 5 for r in range(h))]

    # Marker intersections can interrupt a boundary line, so also detect
    # regularly spaced separator positions by their mostly-5 appearance.
    if len(rs) < 2:
        rs = [r for r in range(h) if grid[r].count(5) >= w - 2]
    if len(cs) < 2:
        cs = [c for c in range(w) if sum(grid[r][c] == 5 for r in range(h)) >= h - 2]

    def regular(lines):
        if len(lines) < 2:
            return lines
        ds = [b-a for a,b in zip(lines, lines[1:])]
        step = max(set(ds), key=ds.count)
        return [p for p in lines if (p-lines[0]) % step == 0]

    rs, cs = regular(rs), regular(cs)
    if not rs or not cs:
        return [[8]]

    # Include the final boundary where present; output one value per block.
    out = [[8 for _ in range(max(1, len(cs)-1))]
              for _ in range(max(1, len(rs)-1))]
    for y, r in enumerate(rs[:-1]):
        for x, c in enumerate(cs[:-1]):
            v = grid[r][c]
            if v not in (5, 8):
                out[y][x] = v
    return out
